style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.postimg.cc/28ny0Mk4/f72c0f28-226d-4b54-a53d-5d106478b981.jpg") no-repeat center center fixed;
    background-size: cover !important;
    color: #ffffff !important;
  }

  /* Thanh trên và các phần nền phụ trong Roblox */
  .navbar, .nav-menu, .header, .footer-container {
    background: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(6px);
  }

  /* Các khung nội dung và hộp thông tin */
  .container-section, .profile-card, .content {
    background-color: rgba(20, 20, 20, 0.65) !important;
    border-radius: 10px;
    box-shadow: 0 0 10px rgba(0,0,0,0.4);
  }

  /* Chữ và liên kết */
  a, .text-link {
    color: #00d4ff !important;
  }

  /* Ẩn quảng cáo */
  .ad-container, .ads, .advertisement {
    display: none !important;
  }
}
